#define CHECK(x) do{if(!(x)){fprintf(stderr,"OW_CHECK OPA line%d: %s\n",__LINE__,#x);return 1;}}while(0)
static int baseline(void){int32_t a=1,b=2;OwPin p;CHECK(ow_pin_init(&p,&a,7)==OW_OK);CHECK(ow_pin_check(&p,&a,8)==OW_INVALID&&ow_pin_check(&p,&b,7)==OW_STALE);CHECK(ow_pin_submit(&p,&a,7)==OW_OK&&ow_pin_cancel(&p,7)==OW_OK);CHECK(ow_pin_rebind(&p,&b,7)==OW_BUSY&&p.address==&a&&p.pending);CHECK(ow_pin_complete(&p,7)==OW_OK&&ow_pin_rebind(&p,&b,7)==OW_OK&&ow_pin_complete(&p,7)==OW_INVALID);struct Self{int value;int *inside;} first={1,NULL};first.inside=&first.value;struct Self copied=first;CHECK(copied.inside==&first.value&&copied.inside!=&copied.value);puts("OPA_BASE actual-OwPin thread-address pending-cancel self-copy-live-comparison");return 0;}
static int timeout_case(void){int32_t a=1,b=2;OpaMachine m;uint32_t ticket=91;CHECK(opa_init(&m,&a,7,9)==OW_OK&&opa_submit(&m,&a,7,&ticket)==OW_OK&&ticket==1);CHECK(opa_timeout(&m,ticket,7)==OW_OK&&m.recovery&&m.pin.pending&&m.pin.cancel&&m.async.state==F_CANCEL_REQUESTED&&!m.async.releases);CHECK(opa_rebind(&m,&b,7)==OW_BUSY&&m.pin.address==&a);CHECK(opa_cancel(&m,ticket,7)==OW_OK&&opa_timeout(&m,ticket,7)==OW_OK);puts("OPA_TIMEOUT recovery-required retained-address cancellation-not-quiescence");return 0;}
static int notification(void){int32_t a=1,b=2,out=91;OpaMachine m;uint32_t ticket=0;CHECK(opa_init(&m,&a,7,9)==OW_OK&&opa_submit(&m,&a,7,&ticket)==OW_OK);CHECK(opa_notify(&m,ticket,9,42)==OW_OK&&m.pin.pending&&m.notified&&!m.async.releases);CHECK(opa_rebind(&m,&b,7)==OW_BUSY&&opa_notify(&m,ticket,9,99)==OW_INVALID);/* Abstract backend has now certified quiescence; native adapter separately joins. */CHECK(opa_finish(&m,ticket,7,&out)==OW_OK&&out==42&&!m.pin.pending&&m.async.releases==1&&m.async.state==F_DONE);CHECK(opa_finish(&m,ticket,7,&out)==OW_INVALID&&out==42);puts("OPA_NOTIFICATION different-executor no-early-terminal exact-FAsync-release");return 0;}
static int identities(void){int32_t a=1,out=91;OpaMachine m;uint32_t ticket=92;CHECK(opa_init(&m,&a,7,9)==OW_OK&&opa_submit(&m,&a,7,&ticket)==OW_OK);CHECK(opa_notify(&m,ticket,8,12)==OW_INVALID&&!m.notified);CHECK(opa_notify(&m,ticket+1,9,12)==OW_STALE&&!m.notified);CHECK(opa_timeout(&m,ticket,8)==OW_INVALID&&!m.recovery);CHECK(opa_notify(&m,ticket,9,12)==OW_OK&&opa_finish(&m,ticket,7,&out)==OW_OK);uint32_t old=ticket;CHECK(opa_submit(&m,&a,7,&ticket)==OW_OK&&ticket==old+1);CHECK(opa_notify(&m,old,9,44)==OW_STALE&&opa_cancel(&m,old,7)==OW_STALE&&!m.notified);puts("OPA_IDENTITY stale-ticket wrong-completion-executor owner-policy");return 0;}
static int counters(void){int32_t a=1,out=91;OpaMachine m;uint32_t ticket=92;CHECK(opa_init(&m,&a,7,9)==OW_OK);m.async.releases=UINT32_MAX;CHECK(opa_submit(&m,&a,7,&ticket)==OW_FULL&&!m.pin.pending&&ticket==92&&!m.async.generation);m.async.releases=UINT32_MAX-1;m.async.generation=UINT32_MAX-1;CHECK(opa_submit(&m,&a,7,&ticket)==OW_OK&&ticket==UINT32_MAX);CHECK(opa_notify(&m,ticket,9,12)==OW_OK&&opa_finish(&m,ticket,7,&out)==OW_OK&&m.async.releases==UINT32_MAX&&!m.pin.pending);CHECK(opa_submit(&m,&a,7,&ticket)==OW_FULL&&opa_rebind(&m,&a,7)==OW_OK);puts("OPA_COUNTERS reserve-terminal-capacity final-generation cleanup-remains");return 0;}
typedef struct {pthread_mutex_t mutex;pthread_cond_t condition;unsigned entered,release,calls,foreign,invalid;OpaPort *port;pthread_t owner;int32_t value;} Receiver;
static void receive(void *arg,int32_t value){Receiver *r=arg;OpaObservation untouched={91,92,93,94,95,96};OwStatus q=opa_port_observe(r->port,&untouched);pthread_mutex_lock(&r->mutex);r->foreign=!pthread_equal(pthread_self(),r->owner);r->invalid=q==OW_INVALID&&untouched.pending==91;r->value=value;++r->calls;r->entered=1;pthread_cond_broadcast(&r->condition);while(!r->release)pthread_cond_wait(&r->condition,&r->mutex);pthread_mutex_unlock(&r->mutex);}
static int hosted(void){OwAllocator cells={0};V4Allocator allocator=ow_allocator(&cells);int32_t *a=allocator.take(allocator.context,3),*b=allocator.take(allocator.context,2);CHECK(a&&b);for(unsigned i=0;i<3;++i)a[i]=-1;OpaPort port={0};CHECK(opa_port_init(&port,a,3)==OW_OK);Receiver r={.mutex=PTHREAD_MUTEX_INITIALIZER,.condition=PTHREAD_COND_INITIALIZER,.port=&port,.owner=pthread_self()};uint32_t ticket=0,unchanged=91;int32_t result=92;CHECK(opa_port_start(&port,40,receive,&r,&ticket)==OW_OK);CHECK(opa_port_cancel(&port,ticket,1)==OW_OK&&opa_port_rebind(&port,b,2)==OW_BUSY&&opa_port_destroy(&port)==OW_BUSY);CHECK(opa_port_join(&port,ticket,0,&result)==OW_BUSY&&result==92);CHECK(opa_port_allow_backend(&port,ticket)==OW_OK);pthread_mutex_lock(&r.mutex);while(!r.entered)pthread_cond_wait(&r.condition,&r.mutex);CHECK(r.calls==1&&r.foreign&&r.invalid&&r.value==123);pthread_mutex_unlock(&r.mutex);OpaObservation observed;CHECK(opa_port_observe(&port,&observed)==OW_OK&&observed.pending&&observed.recovery&&observed.notified&&!observed.done&&!observed.releases);CHECK(opa_port_join(&port,ticket,0,&result)==OW_BUSY&&result==92&&opa_port_start(&port,3,receive,&r,&unchanged)==OW_BUSY&&unchanged==91);pthread_mutex_lock(&r.mutex);r.release=1;pthread_cond_broadcast(&r.condition);pthread_mutex_unlock(&r.mutex);CHECK(opa_port_join(&port,ticket,1,&result)==OW_OK&&result==123);CHECK(a[0]==40&&a[1]==41&&a[2]==42&&opa_port_observe(&port,&observed)==OW_OK&&!observed.pending&&!observed.recovery&&observed.releases==1);CHECK(opa_port_rebind(&port,b,2)==OW_OK);allocator.release(allocator.context,a);CHECK(cells.live==1);CHECK(opa_port_start(&port,10,receive,&r,&ticket)==OW_OK&&ticket==2&&opa_port_allow_backend(&port,ticket)==OW_OK&&opa_port_join(&port,ticket,1,&result)==OW_OK&&result==21);CHECK(b[0]==10&&b[1]==11&&r.calls==2);CHECK(opa_port_join(&port,ticket,0,&result)==OW_INVALID);CHECK(opa_port_destroy(&port)==OW_OK);allocator.release(allocator.context,b);CHECK(!cells.live&&cells.releases==2&&pthread_cond_destroy(&r.condition)==0&&pthread_mutex_destroy(&r.mutex)==0);puts("OPA_HOST actual-foreign-callback late-write-after-timeout notification-held join-before-reuse typed-owner-release");return 0;}
static int oracle(void){char word[16];while(scanf("%15s",word)==1){int32_t a=1,b=2,value=91;OpaMachine m;uint32_t ticket=92;if(opa_init(&m,&a,7,9)!=OW_OK)return 2;for(unsigned i=0;word[i]&&word[i]!='-';++i){OwStatus q;switch(word[i]){case 's':q=opa_submit(&m,m.pin.address,7,&ticket);break;case 'c':q=opa_cancel(&m,m.async.generation,7);break;case 't':q=opa_timeout(&m,m.async.generation,7);break;case 'n':q=opa_notify(&m,m.async.generation,9,42);break;case 'f':q=opa_finish(&m,m.async.generation,7,&value);break;case 'r':q=opa_rebind(&m,m.pin.address==&a?&b:&a,7);break;case 'w':q=opa_notify(&m,m.async.generation,8,77);break;case 'x':q=opa_notify(&m,m.async.generation+1,9,88);break;default:return 2;}printf("%d,%u,%u,%u,%u,%u,%u,%u,%d,%u,%d,%u;",q,m.pin.address==&a?0u:1u,m.pin.pending,m.pin.cancel,m.notified,m.recovery,m.async.generation,m.async.releases,m.async.state,ticket,value,m.result==42?1u:0u);}puts("");}return ferror(stdin)?2:0;}
static int metrics(void){int32_t a=0,result=0;OpaMachine m;uint32_t ticket=0;CHECK(opa_init(&m,&a,7,9)==OW_OK);double times[7];unsigned sum=0;for(unsigned k=0;k<7;++k){clock_t begin=clock();for(unsigned i=0;i<10000;++i){CHECK(opa_submit(&m,&a,7,&ticket)==OW_OK&&opa_notify(&m,ticket,9,42)==OW_OK&&opa_finish(&m,ticket,7,&result)==OW_OK);sum+=(unsigned)result;}times[k]=(double)(clock()-begin)/CLOCKS_PER_SEC;}printf("{\"iterations\":10000,\"checksum\":%u,\"terminal_releases\":%u,\"machine_size\":%zu,\"port_size\":%zu,\"seconds\":[",sum,m.async.releases,sizeof(OpaMachine),sizeof(OpaPort));for(unsigned i=0;i<7;++i)printf("%s%.9f",i?",":"",times[i]);puts("]}");return 0;}
