int main(int argc,char **argv){if(argc!=2)return 2;if(!strcmp(argv[1],"pin_async_base"))return baseline();if(!strcmp(argv[1],"pin_async_timeout"))return timeout_case();if(!strcmp(argv[1],"pin_async_notification"))return notification();if(!strcmp(argv[1],"pin_async_identity"))return identities();if(!strcmp(argv[1],"pin_async_counters"))return counters();if(!strcmp(argv[1],"pin_async_host"))return hosted();if(!strcmp(argv[1],"pin_async_dma"))return pin_dma_test();if(!strcmp(argv[1],"oracle"))return oracle();if(!strcmp(argv[1],"metrics"))return metrics();return 2;}
